ALTER TABLE bank_transactions ADD COLUMN IF NOT EXISTS match_status TEXT NOT NULL DEFAULT 'UNMATCHED';
ALTER TABLE bank_transactions ADD COLUMN IF NOT EXISTS match_confidence NUMERIC(5,2);
ALTER TABLE bank_transactions ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT now();
DO $$ BEGIN ALTER TABLE bank_transactions ADD CONSTRAINT bank_transactions_match_status_check CHECK(match_status IN('UNMATCHED','SUGGESTED','MATCHED','IGNORED')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS bank_import_batches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id),bank_account_id UUID NOT NULL REFERENCES bank_accounts(id),file_name TEXT NOT NULL,source_type TEXT NOT NULL DEFAULT 'CSV',row_count INTEGER NOT NULL DEFAULT 0,inserted_count INTEGER NOT NULL DEFAULT 0,duplicate_count INTEGER NOT NULL DEFAULT 0,error_count INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'COMPLETED',errors JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank_reconciliations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id),bank_transaction_id UUID NOT NULL REFERENCES bank_transactions(id) ON DELETE CASCADE,journal_id UUID REFERENCES journal_entries(id),status TEXT NOT NULL CHECK(status IN('MATCHED','SUGGESTED','REJECTED')),confidence NUMERIC(5,2) NOT NULL DEFAULT 0,reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES organizations(id),file_name TEXT NOT NULL,mime_type TEXT NOT NULL,document_type TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(document_type IN('INVOICE','BANK_STATEMENT','TAX_DOCUMENT','OTHER','UNKNOWN')),sha256 TEXT NOT NULL,source_text TEXT,extracted_data JSONB,extraction_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(extraction_status IN('PENDING','EXTRACTED','REVIEW','FAILED')),confidence NUMERIC(5,2),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organization_id,sha256));
CREATE TABLE IF NOT EXISTS extraction_fields (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES source_documents(id) ON DELETE CASCADE,field_name TEXT NOT NULL,field_value TEXT,confidence NUMERIC(5,2) NOT NULL DEFAULT 0,source_hint TEXT);
CREATE TABLE IF NOT EXISTS document_links (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES source_documents(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id UUID NOT NULL,relation TEXT NOT NULL DEFAULT 'SOURCE');
CREATE INDEX IF NOT EXISTS idx_bank_match ON bank_transactions(organization_id,match_status);
CREATE INDEX IF NOT EXISTS idx_documents_org ON source_documents(organization_id,created_at);
CREATE INDEX IF NOT EXISTS idx_document_fields ON extraction_fields(document_id,field_name);
